INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (433, 1, '의존 모듈', '`modprobe` 가 모듈을 올릴 때 **의존 모듈** 은 어떻게 될까요?', 'modules.dep.bin 을 봐요.', NULL, NULL, '[]', 'choice', '["의존 모듈은 직접 하나씩 먼저 올려야 한다", "의존 모듈은 무시된다", "의존 모듈을 자동으로 추가한다", "의존 모듈이 없으면 항상 실패한다"]', 2, 'modprobe 문서는 modules.dep.bin 을 참조해 필요한 의존 모듈을 자동으로 추가한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 2, 'modprobe -r', '`modprobe -r` 는 무엇을 할까요?', '제거예요.', NULL, NULL, '[]', 'choice', '["모듈을 다시 올린다", "의존 모듈까지 제거 시도", "모듈의 설정을 지운다", "모듈 목록을 덤프한다"]', 1, '문서는 -r 이 모듈을 제거하며 의존 모듈이 사용되지 않으면 함께 제거를 시도한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 3, '--dry-run', '`modprobe -n` 은 무엇을 할까요?', '시험이에요.', NULL, NULL, '[]', 'choice', '["삽입·삭제 명령만 하지 않는다", "모듈을 삽입하지만 설정은 무시", "모듈을 삭제만 하고 삽입은 하지 않음", "의존 모듈만 삽입"]', 0, '문서는 -n/--dry-run 이 모듈 삽입·삭제 및 install·remove 명령 실행을 하지 않고 나머지 작업만 수행한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 4, '-v 옵션', '`modprobe -v` 는 무엇을 할까요?', '자세히예요.', NULL, NULL, '[]', 'choice', '["오류 메시지를 숨긴다", "버전 정보를 제거한다", "유효한 설정을 덤프한다", "수행 중인 작업을 출력한다"]', 3, '문서는 평소에는 문제가 생길 때만 메시지를 출력하며 -v 는 수행 중인 작업을 출력한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 5, '-a 옵션', '`modprobe -a` 는 무엇을 할까요?', 'all 이에요.', NULL, NULL, '[]', 'choice', '["모든 모듈을 제거한다", "모든 별칭을 출력한다", "주어진 모든 모듈을 삽입", "모든 설정 파일을 읽는다"]', 2, '문서는 -a/--all 이 명령행에 주어진 모든 모듈 이름을 삽입한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 6, '-f 옵션', '`modprobe -f` 는 무엇과 같을까요?', '버전 검사를 무시해요.', NULL, NULL, '[]', 'choice', '["--dry-run 과 --verbose 를 함께 쓰는 것", "--force-vermagic + --force-modversion", "--remove 와 --all 을 함께 쓰는 것", "--show-config 와 --quiet 를 함께 쓰는 것"]', 1, '문서는 -f/--force 가 --force-vermagic 과 --force-modversion 을 함께 쓰는 것과 같으며 버전 정보를 제거한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 7, '-c 옵션', '`modprobe -c` 는 무엇을 할까요?', '설정을 보여 줘요.', NULL, NULL, '[]', 'choice', '["유효한 설정을 출력한 뒤 종료한다", "모듈을 삽입한 뒤 종료한다", "모듈 목록을 출력한다", "의존성을 다시 계산한다"]', 0, '문서는 -c/--show-config 가 유효한 설정을 출력한 뒤 종료한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 8, '-S 옵션', '`modprobe -S` 는 무엇을 정할까요?', '커널 버전이에요.', NULL, NULL, '[]', 'choice', '["모듈이 쓸 메모리 크기를 정한다", "모듈 로드 순서를 정한다", "설정 파일 디렉터리를 정한다", "지정한 커널 버전으로 위치 결정"]', 3, '문서는 -S 가 uname(2) 대신 지정한 커널 버전을 써서 모듈 위치를 정한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 9, '- 와 _', '모듈 이름의 `-` 와 `_` 는 어떻게 취급될까요?', '같아요.', NULL, NULL, '[]', 'choice', '["서로 다른 모듈로 취급된다", "_ 만 허용된다", "자동으로 변환되어 차이가 없다", "- 는 오류로 거부된다"]', 2, '문서는 모듈 이름의 - 와 _ 를 자동으로 변환하므로 차이가 없다고 설명합니다.', NULL, NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 10, '시험 실행', '모듈을 실제로 **삽입·삭제하지 않고** 시험하는 옵션입니다. 빈칸을 채우세요.', '"드라이 런" 이에요.', NULL, NULL, '[]', 'fill', '["-n", "-r", "-a", "-c"]', NULL, '-n/--dry-run 은 삽입·삭제와 install·remove 명령 실행을 하지 않고 나머지를 수행합니다.', '[0]', 'modprobe {0} dummy', NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 11, '모듈 제거', '모듈을 **제거** 하는 옵션입니다. 빈칸을 채우세요.', '"remove" 의 r 이에요.', NULL, NULL, '[]', 'fill', '["-r", "-n", "-a", "-c"]', NULL, '-r 은 모듈을 제거하며 의존 모듈이 사용되지 않으면 함께 제거를 시도합니다.', '[0]', 'modprobe {0} veth', NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]'),
  (433, 12, '모듈 로드 흐름', '의존성이 있는 모듈을 올리는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '의존 정보 → 조회 → 의존 → 대상이에요.', NULL, NULL, '[]', 'order', '["`depmod` 가 의존 정보 파일 `modules.dep.bin` 을 만든다", "`modprobe` 가 그 파일을 참조해 필요한 의존 모듈을 찾는다", "의존 모듈을 먼저 삽입한다", "대상 모듈을 삽입한다"]', NULL, '문서의 depmod 와 의존 모듈 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "modprobe(8) man page", "url": "https://man7.org/linux/man-pages/man8/modprobe.8.html"}]');
